const ESI = {}; // 이미지 + 피격용 흰 실루엣
for (const k in ES) {
  ESI[k] = {};
  for (const a in ES[k]) {
    const im = new Image(), o = { im, wh: null };
    im.onload = () => {
      const c = document.createElement('canvas'); c.width = im.width; c.height = im.height;
      const x = c.getContext('2d'); x.drawImage(im, 0, 0);
      x.globalCompositeOperation = 'source-in'; x.fillStyle = '#fff'; x.fillRect(0, 0, c.width, c.height);
      o.wh = c;
    };
    im.src = `assets/enemies/${k}_${a}.png`;
    ESI[k][a] = o;
  }
}
const esHas = (k) => !!(ES[k] && ESI[k].idle?.im.complete && ESI[k].idle.im.naturalWidth);

let corpses = []; // 쓰러지는 연출

// 지금 상태에 맞는 동작/프레임 고르기
function esPick(e) {
  const A = ES[e.t], has = (a) => A[a] && ESI[e.t][a].im.naturalWidth;
  const n = (a) => A[a].length;
  // 이동 여부 (그릴 때마다 위치 변화로 판단)
  const mv = Math.abs(e.x - (e.lx ?? e.x)); e.lx = e.x;
  e.mvS = (e.mvS || 0) * 0.8 + mv * 0.2;
  if (e.cast > (e.castP || 0) + 0.01) e.castM = e.cast;
  e.castP = e.cast;
  // 피격 / 기절
  if (has('hurt') && (e.stn > 0 || e.fl > 0 || Math.abs(e.kx) > 80)) return ['hurt', e.stn > 0 || Math.abs(e.kx) < 80 ? n('hurt') - 1 : 0];
  // 닌자 회피
  if (has('dash') && e.evT > 0) return ['dash', Math.min(n('dash') - 1, ((0.35 - e.evT) / 0.35 * n('dash')) | 0)];
  // 공중
  if (has('jump') && !e.g && !e.D.fly) return ['jump', e.vy < 0 ? 0 : n('jump') - 1];
  // 시전
  if (has('cast') && e.cast > 0 && e.castM) return ['cast', Math.min(n('cast') - 1, ((1 - e.cast / e.castM) * n('cast')) | 0)];
  // 활쏘기: 쏘기 직전 조준 → 쏜 직후 시위 놓기
  if (has('shoot')) {
    if (e.sh < 0.45) return ['shoot', e.sh > 0.22 ? 0 : 1];
    if (e.sh > 1.85 && e.sh <= 2.2) return ['shoot', e.sh > 2.02 ? 2 : 3];
  }
  // 근접 공격: 마왕이나 소환수에게 붙어 있을 때
  if (has('attack')) {
    const near = (x, y) => Math.abs(x - e.x) < e.w / 2 + 60 && y > e.y - e.h - 20 && y - 100 < e.y;
    if (near(p.x, p.y) || e.ac > 0.45) return ['attack', ((time * 9 + e.ph) | 0) % n('attack')];
  }
  if (e.mvS > 0.35 && has('walk')) {
    const rate = 7 * Math.min(2, Math.max(0.7, e.sp / 80)) * (e.bf > 0 ? 1.4 : 1);
    return ['walk', ((time * rate + e.ph) | 0) % n('walk')];
  }
  return ['idle', ((time * 2 + e.ph) | 0) % n('idle')];
}

// 한 프레임 그리기 (발 기준). white: 피격 번쩍임 세기 0~1
function esDraw(key, anim, i, x, y, dir, h, alpha = 1, white = 0) {
  const o = ESI[key][anim], F = ES[key][anim][i];
  if (!o || !F || !o.im.naturalWidth) return false;
  const k = (h * ES_SCALE) / ES_STAND, [fx, fy, fw, fh, ax] = F;
  g.save(); g.translate(x, y); g.scale(dir, 1); g.globalAlpha = alpha;
  g.drawImage(o.im, fx, fy, fw, fh, -ax * k, -fh * k, fw * k, fh * k);
  if (white > 0 && o.wh) { g.globalAlpha = alpha * white; g.drawImage(o.wh, fx, fy, fw, fh, -ax * k, -fh * k, fw * k, fh * k); }
  g.restore();
  return true;
}

function esDrawEnemy(e, sx) {
  const [a, i] = esPick(e);
  return esDraw(e.t, a, i, sx, e.y, e.dir, e.h, 1, e.fl > 0 ? 0.75 : 0);
}

// 처치 시 쓰러지는 연출 등록 (kill에서 호출)
function esDie(e) {
  if (!ES[e.t]?.death || !esHas(e.t)) return;
  corpses.push({ key: e.t, x: e.x, y: e.y, dir: e.dir, h: e.h, t0: time });
}
function esDrawCorpses() {
  const FD = 0.11, HOLD = 1.1, FADE = 0.6;
  corpses = corpses.filter((c) => time - c.t0 < ES[c.key].death.length * FD + HOLD + FADE);
  for (const c of corpses) {
    const sx = c.x - cam; if (sx < -200 || sx > W + 200) continue;
    const t = time - c.t0, n = ES[c.key].death.length, i = Math.min(n - 1, (t / FD) | 0);
    const end = n * FD + HOLD, al = t > end ? 1 - (t - end) / FADE : 1;
    esDraw(c.key, 'death', i, sx, c.y, c.dir, c.h, Math.max(0, al));
  }
}
